  "churn_by_activation_speed": "select\n    activation_speed,\n    count(*) as accounts,\n    sum(case when churn_type is not null then 1 else 0 end) as churned_accounts,\n    avg(case when churn_type is not null then 1.0 else 0.0 end) as churn_rate\nfrom analytics.dim_accounts\nwhere is_customer and not is_excluded and activation_speed is not null\n  and live_date >= (select min(date_day) from analytics.dim_date where is_in_data_window)\n  [[ and segment = {{segment}} ]]\n  [[ and lead_source = {{lead_source}} ]]\ngroup by activation_speed\norder by activation_speed\n",
  "cohort_logo_retention": "select cohort_quarter, months_since_live, logo_retention, cohort_accounts\nfrom analytics.fct_cohort_retention\norder by cohort_quarter, months_since_live\n",
  "cohort_retention_grid": "with accounts as (\n    select *\n    from analytics.fct_cohort_account_months\n    where 1 = 1\n      [[ and segment = {{segment}} ]]\n      [[ and lead_source = {{lead_source}} ]]\n),\nsizes as (\n    select cohort_quarter, count(distinct account_id) as cohort_accounts\n    from accounts\n    group by cohort_quarter\n)\nselect\n    a.cohort_quarter,\n    a.months_since_live,\n    s.cohort_accounts,\n    count(*) filter (where a.is_active) as active_accounts,\n    count(*) filter (where a.is_active) * 1.0 / s.cohort_accounts as logo_retention,\n    sum(a.net_revenue_usd) as net_revenue_usd,\n    sum(sum(a.net_revenue_usd)) over (partition by a.cohort_quarter order by a.months_since_live) as revenue_to_date_usd,\n    sum(a.net_revenue_usd) / nullif(sum(a.base_revenue_usd), 0) as nrr\nfrom accounts as a\ninner join sizes as s on a.cohort_quarter = s.cohort_quarter\nwhere a.months_since_live <= 12\ngroup by a.cohort_quarter, a.months_since_live, s.cohort_accounts\n-- complete cells only: every account in the (filtered) cohort has reached this month\nhaving count(*) = s.cohort_accounts\norder by a.cohort_quarter, a.months_since_live\n",
  "corridor_rail_failures": "select\n    d.corridor,\n    d.rail,\n    sum(d.txn_count) as transactions,\n    sum(d.failed_count) as failed,\n    sum(d.failed_count) * 1.0 / nullif(sum(d.txn_count), 0) as failure_rate\nfrom analytics.fct_account_daily as d\ninner join analytics.dim_accounts as a on d.account_id = a.account_id\nwhere 1 = 1\n  [[ and d.activity_date >= {{date_from}} ]]\n  [[ and d.activity_date <= {{date_to}} ]]\n  [[ and a.segment = {{segment}} ]]\n  [[ and d.corridor = {{corridor}} ]]\n  [[ and a.owner_id = {{owner_id}} ]]\ngroup by d.corridor, d.rail\norder by d.corridor, d.rail\n",
  "days_in_stage": "select\n    t.stage,\n    percentile_cont(0.5) within group (order by t.days_in_stage) as median_days_in_stage,\n    count(*) as stage_entries\nfrom analytics.fct_stage_transitions as t\ninner join analytics.dim_stages as s on t.stage = s.stage\nwhere s.is_open_stage and t.days_in_stage is not null\n  [[ and t.entered_at >= {{date_from}} ]]\n  [[ and t.entered_at < cast({{date_to}} as date) + 1 ]]\n  [[ and t.segment = {{segment}} ]]\n  [[ and t.lead_source = {{lead_source}} ]]\n  [[ and t.owner_id = {{owner_id}} ]]\ngroup by t.stage, s.stage_rank\norder by s.stage_rank\n",
  "deal_outcomes": "select\n    g.dimension,\n    coalesce(g.grp, 'unknown') as grp,\n    count(*) as deals,\n    count(*) filter (where o.outcome = 'won') as won,\n    count(*) filter (where o.outcome = 'lost') as lost,\n    count(*) filter (where o.outcome = 'open') as still_open,\n    avg(case when o.outcome = 'won' then 1.0 else 0.0 end) as won_share,\n    coalesce(sum(o.amount_usd) filter (where o.outcome = 'won'), 0) as won_usd,\n    coalesce(sum(o.amount_usd) filter (where o.outcome = 'lost'), 0) as lost_usd,\n    coalesce(sum(o.amount_usd) filter (where o.outcome = 'open'), 0) as open_usd,\n    mode() within group (order by o.furthest_stage_rank)\n    filter (where o.outcome = 'lost') as lost_stage_rank\nfrom analytics.fct_opportunities as o\ncross join lateral (\n    values\n        ('segment', o.segment),\n        ('lead_source', o.lead_source),\n        ('rep', o.rep_name),\n        ('team', o.rep_team),\n        ('industry', o.industry)\n) as g (dimension, grp)\nwhere 1 = 1\n  [[ and o.created_date >= {{date_from}} ]]\n  [[ and o.created_date <= {{date_to}} ]]\n  [[ and o.segment = {{segment}} ]]\n  [[ and o.lead_source = {{lead_source}} ]]\n  [[ and o.owner_id = {{owner_id}} ]]\ngroup by g.dimension, coalesce(g.grp, 'unknown')\norder by g.dimension, deals desc, grp\n",
  "deals_list": "select\n    o.opportunity_id,\n    o.account_id,\n    a.name as account_name,\n    o.rep_name,\n    o.segment,\n    o.lead_source,\n    o.stage,\n    o.outcome,\n    o.amount_usd,\n    o.created_date,\n    o.close_date,\n    o.is_past_due\nfrom analytics.fct_opportunities as o\ninner join analytics.dim_accounts as a on o.account_id = a.account_id\nwhere 1 = 1\n  [[ and o.created_date >= {{date_from}} ]]\n  [[ and o.created_date <= {{date_to}} ]]\n  [[ and o.segment = {{segment}} ]]\n  [[ and o.lead_source = {{lead_source}} ]]\n  [[ and o.owner_id = {{owner_id}} ]]\norder by o.amount_usd desc nulls last, o.opportunity_id\nlimit 100\n",
  "dispute_rate_by_month": "select\n    d.activity_month as month,\n    sum(d.disputes_opened + d.returns_opened) * 1.0 / nullif(sum(d.succeeded_count), 0) as dispute_return_rate,\n    sum(d.disputes_opened) as disputes,\n    sum(d.returns_opened) as returns,\n    sum(d.succeeded_count) as succeeded\nfrom analytics.fct_account_daily as d\ninner join analytics.dim_accounts as a on d.account_id = a.account_id\nwhere 1 = 1\n  [[ and d.activity_date >= {{date_from}} ]]\n  [[ and d.activity_date <= {{date_to}} ]]\n  [[ and a.segment = {{segment}} ]]\n  [[ and d.corridor = {{corridor}} ]]\n  [[ and a.owner_id = {{owner_id}} ]]\ngroup by 1\norder by 1\n",
  "dispute_return_rate": "select\n    sum(d.disputes_opened + d.returns_opened) * 1.0 / nullif(sum(d.succeeded_count), 0) as dispute_return_rate\nfrom analytics.fct_account_daily as d\ninner join analytics.dim_accounts as a on d.account_id = a.account_id\nwhere 1 = 1\n  [[ and d.activity_date >= {{date_from}} ]]\n  [[ and d.activity_date <= {{date_to}} ]]\n  [[ and a.segment = {{segment}} ]]\n  [[ and d.corridor = {{corridor}} ]]\n  [[ and a.owner_id = {{owner_id}} ]]\n",
  "failure_rate": "select sum(d.failed_count) * 1.0 / nullif(sum(d.txn_count), 0) as failure_rate\nfrom analytics.fct_account_daily as d\ninner join analytics.dim_accounts as a on d.account_id = a.account_id\nwhere 1 = 1\n  [[ and d.activity_date >= {{date_from}} ]]\n  [[ and d.activity_date <= {{date_to}} ]]\n  [[ and a.segment = {{segment}} ]]\n  [[ and d.corridor = {{corridor}} ]]\n  [[ and a.owner_id = {{owner_id}} ]]\n",
  "failure_rate_by_corridor": "select\n    d.activity_month as month,\n    d.corridor,\n    sum(d.failed_count) * 1.0 / nullif(sum(d.txn_count), 0) as failure_rate,\n    sum(d.txn_count) as transactions,\n    sum(d.failed_count) as failed\nfrom analytics.fct_account_daily as d\ninner join analytics.dim_accounts as a on d.account_id = a.account_id\nwhere 1 = 1\n  [[ and d.activity_date >= {{date_from}} ]]\n  [[ and d.activity_date <= {{date_to}} ]]\n  [[ and a.segment = {{segment}} ]]\n  [[ and d.corridor = {{corridor}} ]]\n  [[ and a.owner_id = {{owner_id}} ]]\ngroup by 1, 2\norder by 1, 2\n",
  "filter_accounts": "select account_id, name as account_name\nfrom analytics.dim_accounts\nwhere is_customer and not is_excluded\norder by name\n",
